export const labels={value:'Operational value',feasibility:'Prototype feasibility',data:'Demo data readiness',safety:'Reviewability',evidence:'Evidence strength',clarity:'Demonstration clarity'};
export function score(c,weights){const total=Object.values(weights).reduce((a,b)=>a+b,0);return total?Math.round(Object.entries(weights).reduce((a,[k,w])=>a+w*c.scores[k]/5,0)/total*100):0}
export function rank(data,weights){return [...data.cases].sort((a,b)=>score(b,weights)-score(a,weights)||a.title.localeCompare(b.title))}
export function filterCases(data,weights,{scope='',area='',level='',source='',query=''}={}){return rank(data,weights).filter(c=>(!scope||c.category===scope)&&(!area||c.sub_category===area)&&(!level||c.risk===level)&&(!source||data.examples.some(e=>e.source_id===source&&e.case_ids.includes(c.id)))&&[c.title,c.workflow,c.user,c.sub_category,c.sector,...(c.examples||[]).map(id=>[data.examples.find(e=>e.id===id).organization,data.examples.find(e=>e.id===id).name].join(' '))].join(' ').toLowerCase().includes(query.toLowerCase()))}
export function reviewMessage(message){const t=message.trim().toLowerCase();if(!t)return null;let category='Manual review',queue='Front desk',draft='Thank you for your message. Our team will review your request.',reference='No matching FAQ rule. Staff review required.';if(/symptom|pain|medicat|treatment|diagnos|bleed|breath|chest|dizzy|fever|sick|dose|rash|unwell/.test(t)){category='Clinical review required';queue='Qualified care team';draft='Your message needs review by a qualified care team. No clinical reply has been drafted.';reference='Fictional FAQ: clinical questions require qualified review.'}else if(/book|reschedul|appointment|cancel/.test(t)){category='Booking request';draft='Thank you. Our booking team will review your requested change and confirm availability before updating the appointment.';reference='Fictional FAQ: booking changes require staff confirmation.'}else if(/invoice|bill|receipt|payment/.test(t)){category='Billing request';queue='Billing team';draft='Thank you. Our billing team can assist with invoice copies after identity verification through the approved process.';reference='Fictional FAQ: invoice copies require identity verification.'}return {category,queue,draft,reference}}
